import{_ as s,a0 as i,w as a,s as l,ao as r,I as p,x as u,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在Ubuntu 13.10中給菜單添加圖標 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 13.10中給菜單添加圖標 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 13.10中給菜單添加圖標 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 13.10中給菜單添加圖標 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to add icons to menus in Ubuntu 13.10","title":"如何在Ubuntu 13.10中給菜單添加圖標","tag":"201311","desc":""},"relativePath":"201311/How to add icons to menus in Ubuntu 13.10.md","filePath":"[post].md"}'),d={name:"201311/How to add icons to menus in Ubuntu 13.10.md"};function b(m,t,T,f,g,U){const n=i("Link");return a(),l("div",null,[t[11]||(t[11]=r('<h1 id="如何在ubuntu-13-10中給菜單添加圖標" tabindex="-1">如何在Ubuntu 13.10中給菜單添加圖標 <a class="header-anchor" href="#如何在ubuntu-13-10中給菜單添加圖標" aria-label="Permalink to “如何在Ubuntu 13.10中給菜單添加圖標”">​</a></h1><p>通常，使用Ubuntu 13.10的用户會會對默認的程序、偏好和功能進行優化，才能得到更好的用户體驗。</p><p>Ubuntu的用户體驗是可以優化調整的，因此用户可以通過一些工具來修改和調整那些默認設置，比如使用Ubuntu Tweak。</p><p>默認情況下，Ubuntu禁用了內部菜單的圖標，即，右鍵點擊桌面打開右鍵菜單時，菜單中只包含文本而且沒有相應的圖標。</p><p>不過，在Ubuntu 13.10的菜單中添加圖標是很簡單的：</p><ul><li><p>安裝Ubuntu Tweak</p><p>sudo add-apt-repository ppa:tualatrix/ppa</p><p>sudo apt-get update</p><p>sudo apt-get install ubuntu-tweak</p></li><li><p>啓動Ubuntu Tweak，並導航到<code>Tweaks--&gt;Miscellaneous</code></p></li><li><p>選中 <code>Menus have icons</code></p></li></ul><p><strong>結果</strong>：現在右鍵點擊桌面，圖標就會在菜單中顯示, 圖標顯示也會在其他軟件的右鍵菜單出現(例如， Nautilus, Firefox, Gedit中的菜單等等)。</p><p><img src="http://iloveubuntu.net/pictures_me/menu%20icon%203%20ubuntu%2013.10.png" alt=""></p><p><img src="http://iloveubuntu.net/pictures_me/menu%20icons%20ubuntu%2013.10%201.png" alt=""></p><p><img src="http://iloveubuntu.net/pictures_me/menu%20icons%20ubuntu%2013.10%202.png" alt=""></p><p>這樣在最常用的右鍵菜單中加上新增的圖標，菜單會更加清晰和美麗，特別是使用單色圖標菜單顯示圖標時。</p><hr>',12)),p("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://iloveubuntu.net/how-add-icons-menus-ubuntu-1310"},{default:o(()=>[...t[0]||(t[0]=[u("http://iloveubuntu.net/how-add-icons-menus-ubuntu-1310",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=u("譯者：",-1)),e(n,{href:"http://blog.csdn.net/u011459130"},{default:o(()=>[...t[2]||(t[2]=[u("Yu-Fei",-1)])]),_:1}),t[5]||(t[5]=u(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[u("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[u("Linux中國",-1)])]),_:1}),t[10]||(t[10]=u(" 榮譽推出",-1))])])}const w=s(d,[["render",b]]);export{C as __pageData,w as default};
